import { Marked, type RendererThis, type Token, type Tokens, type TokenizerAndRendererExtension } from 'marked';
import DomPurify from 'isomorphic-dompurify';
import type { MaybeRefOrGetter } from 'vue';
import { slugify, stripFrontmatter, type TocEntry } from '~/utils/guides';

const LINK_ICON =
  '<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"></path><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"></path></svg>';

function escapeHtml(text: string): string {
  return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// Reconstructs markup-stripped plain text from parsed inline tokens (headings have no
// nested extensions here, so a leaf's `.text` combined with recursion into `.tokens` is enough).
function plainText(tokens: Token[] | undefined): string {
  if (!tokens) return '';
  return tokens
    .map((token) => {
      const node = token as { tokens?: Token[]; text?: string };
      return node.tokens && node.tokens.length ? plainText(node.tokens) : (node.text ?? '');
    })
    .join('');
}

// Same-page slug de-duplication (matches markdown-it-anchor's default `-1`, `-2`, ... suffixing).
// Reset per render pass — see `html`/`toc` below for why one counter per pass is required.
const headingSlugs = { counts: new Map<string, number>() };

function nextSlug(text: string): string {
  const base = slugify(text);
  const seen = headingSlugs.counts.get(base) ?? 0;
  headingSlugs.counts.set(base, seen + 1);
  return seen === 0 ? base : `${base}-${seen}`;
}

// Same tab only for in-page anchors and same-origin `/docs` pages (in-app navigation).
// Every other link — external, or another in-app section — opens in a new tab.
export function isDocsHref(href: string): boolean {
  if (!href) return false;
  if (href.startsWith('#')) return true;
  try {
    const base = window.location.href;
    const url = new URL(href, base);
    const sameOrigin = typeof window === 'undefined' || url.origin === window.location.origin;
    return sameOrigin && (url.pathname === '/docs' || url.pathname.startsWith('/docs/'));
  } catch {
    return false;
  }
}

// VitePress-style custom containers: `::: <type> [custom title]` … `:::`
const CALLOUT_TITLES: Record<string, string> = {
  tip: 'TIP',
  info: 'INFO',
  warning: 'WARNING',
  danger: 'DANGER',
};

const CONTAINER_RE = /^ {0,3}::: *(tip|info|warning|danger|details) *([^\n]*?) *\n([\s\S]*?)\n {0,3}::: *(?:\n|$)/;

const containerExtension: TokenizerAndRendererExtension = {
  name: 'container',
  level: 'block',
  start(src) {
    const match = /(?:^|\n) {0,3}:::/.exec(src);
    return match?.index === undefined ? undefined : match.index + (match[0].startsWith('\n') ? 1 : 0);
  },
  tokenizer(src) {
    const match = CONTAINER_RE.exec(src);
    if (!match) return undefined;
    const [raw, calloutType, title, body] = match;
    return {
      type: 'container',
      raw,
      calloutType,
      title,
      tokens: this.lexer.blockTokens(body, []),
    };
  },
  childTokens: ['tokens'],
  renderer(token) {
    const inner = this.parser.parse(token.tokens as Token[]);
    const type = token.calloutType as string;
    const title = escapeHtml(token.title as string) || (type === 'details' ? 'Details' : CALLOUT_TITLES[type]);
    if (type === 'details') {
      return `<details class="guide-callout guide-callout--details"><summary>${title}</summary>\n${inner}</details>\n`;
    }
    return `<div class="guide-callout guide-callout--${type}"><p class="guide-callout__title">${title}</p>\n${inner}</div>\n`;
  },
};

function heading(this: RendererThis, token: Tokens.Heading): string {
  const body = this.parser.parseInline(token.tokens);
  if (token.depth > 3) return `<h${token.depth}>${body}</h${token.depth}>`;
  const id = nextSlug(plainText(token.tokens));
  return `<h${token.depth} id="${id}">${body}<a class="guide-heading-anchor" href="#${id}" aria-label="Copy link to this section" title="Copy link">${LINK_ICON}</a></h${token.depth}>`;
}

function link(this: RendererThis, token: Tokens.Link): string {
  const body = this.parser.parseInline(token.tokens);
  const href = escapeHtml(token.href);
  const titleAttr = token.title ? ` title="${escapeHtml(token.title)}"` : '';
  const extra = isDocsHref(token.href) ? '' : ' target="_blank" rel="noopener noreferrer"';
  return `<a href="${href}"${titleAttr}${extra}>${body}</a>`;
}

// A dedicated `Marked` instance, kept separate from the app-wide `$marked` plugin and from
// `DashboardMarkdown.vue`'s instance so this config never leaks into other markdown consumers.
const marked = new Marked({ gfm: true, breaks: false });
marked.use({
  extensions: [containerExtension],
  renderer: { heading, link },
});

function collectHeadings(tokens: Token[]): Tokens.Heading[] {
  const out: Tokens.Heading[] = [];
  for (const token of tokens) {
    const node = token as { type: string; tokens?: Token[]; items?: Token[] };
    if (node.type === 'heading') out.push(token as Tokens.Heading);
    if (node.tokens?.length) out.push(...collectHeadings(node.tokens));
    if (node.items?.length) out.push(...collectHeadings(node.items));
  }
  return out;
}

export function useGuideMarkdown(source: MaybeRefOrGetter<string | null | undefined>) {
  const clean = computed(() => stripFrontmatter(toValue(source) ?? ''));

  const html = computed(() => {
    headingSlugs.counts = new Map();
    return DomPurify.sanitize(marked.parse(clean.value, { async: false }) as string, { ADD_ATTR: ['target'] });
  });

  const toc = computed<TocEntry[]>(() => {
    headingSlugs.counts = new Map();
    return collectHeadings(marked.lexer(clean.value))
      .filter((token) => token.depth === 2 || token.depth === 3)
      .map((token) => {
        const text = plainText(token.tokens);
        return { level: token.depth as 2 | 3, text, id: nextSlug(text) };
      });
  });

  return { clean, html, toc };
}
