<template>
  <section class="flex flex-col gap-4">
    <AppLoader v-if="isLoading" subject="page" variant="inline" />
    <AppError
      v-else-if="error"
      :error="error"
      :title="statusCode === 404 ? 'Page not found' : 'Failed to load page'"
      to="/docs"
      action-text="Go Back"
      variant="page"
    />
    <div v-else-if="content" class="flex flex-col gap-4">
      <GuideBreadcrumb :doc-name="pageTitle" />
      <GuideDraftBanner :status="frontmatter.status" :review-note="frontmatter.reviewNote" />
      <GuideToc :entries="toc" />
      <Card>
        <CardContent class="p-6 lg:p-8">
          <ClientOnly>
            <GuideMarkdown :html="html" />
          </ClientOnly>
        </CardContent>
      </Card>
    </div>
    <AppEmpty v-else subject="page" variant="table" />
  </section>
</template>

<script setup lang="ts">
import { Card, CardContent } from '@/components/ui/card';
import type { FetchError } from 'ofetch';
import type { GetDocPageData } from '~/client';
import { getDocPage } from '~/client';

const route = useRoute('docs-slug');

const segments = computed<string[]>(() => {
  const slug = route.params.slug;
  if (Array.isArray(slug)) return slug.filter(Boolean);
  return slug ? [String(slug)] : [];
});

const docPath = computed(() => (segments.value.length ? `${segments.value.join('/')}.md` : ''));

const {
  data: content,
  error,
  isLoading,
} = useQuery({
  key: () => ['docs-page', docPath.value],
  query: () =>
    getDocPage({
      path: {
        doc_path: docPath.value as GetDocPageData['path']['doc_path'],
      },
    }),
  enabled: () => route.name === 'docs-slug',
  staleTime: 0,
});

const { html, toc } = useGuideMarkdown(content);

const frontmatter = computed(() => parseDocFrontmatter(content.value ?? ''));

const statusCode = computed(() => {
  const err = error.value as FetchError | null;
  return err?.statusCode ?? err?.response?.status;
});

const pageTitle = computed(() => {
  const slug = docPath.value.replace(/\.md$/i, '').split('/').pop() ?? '';
  return extractDocTitle(content.value ?? '') ?? (slug ? humanizeSlug(slug) : 'Guide');
});

useHead({ title: pageTitle });
</script>
