<template>
  <!-- eslint-disable-next-line vue/no-v-html -- content is markdown-it output (html:false) sanitized via DOMPurify in useGuideMarkdown -->
  <div class="guide-md" @click="onClick" v-html="html" />
</template>

<script setup lang="ts">
const props = defineProps<{
  /** Sanitized HTML produced by `useGuideMarkdown`. */
  html: string;
}>();

const router = useRouter();

function highlightHeading(id: string) {
  const el = document.getElementById(id);
  if (!el) return;
  el.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

async function onClick(event: MouseEvent) {
  const target = event.target as HTMLElement;

  // 1) Copy a section link when a heading's anchor glyph is clicked.
  const anchor = target.closest('a.guide-heading-anchor') as HTMLAnchorElement | null;
  if (anchor) {
    event.preventDefault();
    const id = decodeURIComponent((anchor.getAttribute('href') ?? '').replace(/^#/, ''));
    if (!id) return;
    const url = `${window.location.origin}${window.location.pathname}#${id}`;
    try {
      await navigator.clipboard.writeText(url);
      showToastSuccess('Link copied');
    } catch {
      showToastError('Could not copy link');
    }
    return;
  }

  // 2) Same-origin /docs links navigate in-app; everything else is marked target=_blank by the renderer.
  const link = target.closest('a[href]') as HTMLAnchorElement | null;
  if (!link || link.target === '_blank') return;
  if (event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
  const raw = link.getAttribute('href') ?? '';
  if (!raw || raw.startsWith('#')) return; // in-page anchors keep native behavior
  const url = new URL(raw, window.location.href);
  if (url.origin !== window.location.origin) return; // safety net
  if (url.pathname !== '/docs' && !url.pathname.startsWith('/docs/')) return; // only docs pages navigate in-app
  event.preventDefault();
  await router.push(url.pathname + url.search + url.hash);
}

watch(
  () => props.html,
  async () => {
    await nextTick();
    const id = decodeURIComponent(window.location.hash.replace(/^#/, ''));
    if (id) highlightHeading(id);
  },
  { immediate: true }
);
</script>

