<template>
  <Collapsible
    v-if="entries.length"
    v-slot="{ open }"
    :default-open="false"
    class="rounded-lg border border-border bg-card"
  >
    <CollapsibleTrigger
      class="flex w-full items-center justify-between gap-2 px-4 py-3 text-base font-semibold text-foreground"
      aria-label="Toggle table of contents"
    >
      <span class="inline-flex items-center gap-2">
        <ListTree class="h-4 w-4 text-muted-foreground" />
        On this page
      </span>
      <ChevronDown
        class="h-4 w-4 text-muted-foreground transition-transform duration-200"
        :class="open ? 'rotate-180' : ''"
      />
    </CollapsibleTrigger>
    <CollapsibleContent>
      <ul class="flex gap-2 md:gap-1 flex-col px-2 pb-3 text-sm">
        <li v-for="entry in entries" :key="entry.id" :class="entry.level === 3 ? 'ml-4' : ''">
          <a
            :href="`#${entry.id}`"
            class="block rounded-md px-2 py-1.5 leading-snug transition-colors hover:bg-accent hover:text-accent-foreground font-medium text-foreground"
            @click.prevent="scrollTo(entry.id)"
          >
            {{ entry.text }}
          </a>
        </li>
      </ul>
    </CollapsibleContent>
  </Collapsible>
</template>

<script setup lang="ts">
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from '@/components/ui/collapsible';
import { ChevronDown, ListTree } from 'lucide-vue-next';

const props = defineProps<{
  entries: TocEntry[];
}>();

function scrollTo(id: string) {
  const el = document.getElementById(id);
  if (!el) return;
  el.scrollIntoView({ behavior: 'smooth', block: 'start' });
  history.replaceState(null, '', `#${id}`);
}
</script>
